import {describeComposition} from './ai-composition-contract.mjs';
export async function readCompositionStream(response,onEvent){
 if(!response.ok){let data;try{data=await response.json();}catch{}throw Error(data?.error||'Composition is unavailable. Try again.');}
 const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',complete=false;
 try{while(true){const {value,done}=await reader.read();buffer+=done?decoder.decode():decoder.decode(value,{stream:true});buffer=buffer.replace(/\r\n/g,'\n');let end;while((end=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,end);buffer=buffer.slice(end+2);const event=frame.split('\n').find(l=>l.startsWith('event:'))?.slice(6).trim(),data=frame.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trim()).join('\n');if(!data)continue;const parsed=JSON.parse(data);if(event==='error')throw Error(parsed.message);if(event==='complete')complete=true;await onEvent(event,parsed);}if(done)break;}if(!complete)throw Error('The connection ended before the plan completed. Retry to continue.');}finally{reader.releaseLock();}
}
export function createAICompositionUI({tiles,canUse,save,build,undo}){
 const launcher=document.createElement('button');launcher.id='ai-composer-toggle';launcher.type='button';launcher.textContent='AI';launcher.title=launcher.ariaLabel='Describe an AI tile';launcher.setAttribute('aria-expanded','false');document.querySelector('#toolbar-tools').prepend(launcher);
 const panel=document.createElement('aside');panel.id='ai-composer';panel.hidden=true;panel.setAttribute('aria-label','AI tile composition');panel.innerHTML=`<div class="ai-heading"><strong>AI tile</strong><button type="button" aria-label="Close AI composer">×</button></div><label>Construction site<select aria-label="AI construction site"></select></label><p class="ai-empty">Choose “AI tile” from the scene picker and drag its blank tile onto the board.</p><form><label>What belongs here?<textarea aria-label="Describe this tile" maxlength="1200" rows="3" placeholder="Make a pack of ferocious lions"></textarea></label><button type="submit">Plan it</button><button type="button" class="ai-cancel" hidden>Cancel request</button></form><p class="ai-status" role="status" aria-live="polite"></p><div class="ai-dialog"></div><div class="ai-actions"><button type="button" class="ai-build" hidden>Build this</button><button type="button" class="ai-undo" hidden>Undo build</button></div><details><summary>Requests for later</summary><ul class="ai-requests"></ul><p>Saved on this device with the tile. New assets must pass review and registration before integration.</p></details>`;document.body.append(panel);
 const select=panel.querySelector('select'),form=panel.querySelector('form'),input=panel.querySelector('textarea'),status=panel.querySelector('.ai-status'),dialog=panel.querySelector('.ai-dialog'),buildButton=panel.querySelector('.ai-build'),undoButton=panel.querySelector('.ai-undo'),cancelButton=panel.querySelector('.ai-cancel');
 let selected='',controller=null,building=false,enabled=null;
 const current=()=>tiles().find(t=>t.id===selected);
 function open(id){if(id)selected=id;panel.hidden=false;launcher.setAttribute('aria-expanded','true');refresh();input.focus();}
 function close(){panel.hidden=true;launcher.setAttribute('aria-expanded','false');launcher.focus();}
 function refresh(){const list=tiles(),old=selected;select.replaceChildren();for(const tile of list){const o=document.createElement('option');o.value=tile.id;o.textContent=tile.ai?.plan?.title||'Blank AI tile';select.append(o);}selected=list.some(t=>t.id===old)?old:list.at(-1)?.id||'';select.value=selected;const tile=current();form.hidden=!tile;select.hidden=!list.length;panel.querySelector('.ai-empty').hidden=!!tile;const plan=tile?.ai?.plan;dialog.textContent=plan?describeComposition(plan):'';buildButton.hidden=!plan?.canBuild||tile.ai.status==='ready';buildButton.textContent=plan?.substitutions.length?'Build with substitutions':'Build this';buildButton.disabled=building||!!controller;undoButton.hidden=!tile?.ai?.previous;undoButton.disabled=building||!!controller;form.querySelector('[type=submit]').disabled=enabled!==true||building||!!controller||tile?.ai?.status==='ready';select.disabled=building||!!controller;input.disabled=building||!!controller||tile?.ai?.status==='ready';const requests=panel.querySelector('.ai-requests');requests.replaceChildren();for(const request of plan?.missing||[]){const li=document.createElement('li');li.textContent=`${request.name} · ${request.kind} · requested`;requests.append(li);}if(!requests.children.length){const li=document.createElement('li');li.textContent='No missing assets requested.';requests.append(li);}}
 launcher.onclick=()=>panel.hidden?open():close();panel.querySelector('.ai-heading button').onclick=close;select.onchange=()=>{selected=select.value;status.textContent='';input.value=current()?.ai?.prompt||'';refresh();};panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();close();}});
 cancelButton.onclick=()=>controller?.abort();
 form.onsubmit=async event=>{event.preventDefault();if(enabled!==true||!canUse()||controller||building)return;const tile=current(),prompt=input.value.trim();if(!tile||!prompt)return;const tileId=tile.id,requestId=crypto.randomUUID();controller=new AbortController();cancelButton.hidden=false;status.textContent='Planning…';refresh();let plan=null;
  try{const response=await fetch('/api/ai-compose',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,requestId}),signal:controller.signal});await readCompositionStream(response,(event,data)=>{if(data.requestId!==requestId)throw Error('Unexpected response. Please retry.');if(event==='status')status.textContent=data.message;if(event==='plan')plan=data.plan;});if(!plan)throw Error('No plan was returned.');if(!tiles().some(t=>t.id===tileId))throw Error('The construction site was removed.');save(tileId,{prompt,plan,status:'planned'});status.textContent=plan.canBuild?'Plan ready. Review it below.':'This request needs assets or behaviors that are not available yet.';}
  catch(error){status.textContent=error.name==='AbortError'?'Request cancelled. Your tile is unchanged.':error.message;}
  finally{controller=null;cancelButton.hidden=true;refresh();}
 };
 buildButton.onclick=async()=>{const tile=current();if(!tile?.ai?.plan||building||controller||!canUse())return;building=true;refresh();try{status.textContent='Loading the existing assets and finding space…';await build(tile.id,tile.ai.plan,message=>{status.textContent=message;});status.textContent='Built. The scene is now using its existing simulation.';}catch(error){status.textContent=error.message;}finally{building=false;refresh();}};
 undoButton.onclick=async()=>{const tile=current();if(!tile||building||controller||!canUse())return;building=true;refresh();try{await undo(tile.id);status.textContent='Build undone.';}catch(error){status.textContent=error.message;}finally{building=false;refresh();}};
 fetch('/api/ai-compose').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{enabled=data.enabled===true;if(!enabled)status.textContent='AI planning is not enabled yet. Your construction site stays saved.';refresh();}).catch(()=>{enabled=false;status.textContent='AI planning is temporarily unavailable. Your construction site stays saved.';refresh();});
 return {open,refresh,get working(){return building||!!controller;}};
}
const style=document.createElement('style');style.textContent=`#ai-composer{position:fixed;z-index:42;right:12px;top:64px;bottom:90px;width:min(350px,calc(100vw - 24px));box-sizing:border-box;overflow:auto;background:var(--app-panel,#fffcf0);color:var(--app-ink,#4c4330);border:1px solid var(--app-border,#ded5b2);border-radius:14px;padding:14px;box-shadow:0 8px 30px #302b2520;font:13px var(--app-font,Manrope,sans-serif)}#ai-composer[hidden]{display:none}#ai-composer .ai-heading{position:sticky;top:-14px;background:var(--app-panel,#fffcf0);z-index:1;padding:8px 0;display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}#ai-composer strong{font:22px Fraunces,serif}#ai-composer label{display:block;margin:10px 0}#ai-composer select,#ai-composer textarea{display:block;box-sizing:border-box;width:100%;margin-top:6px;background:transparent;color:inherit;border:1px solid var(--app-border,#ded5b2);border-radius:8px;padding:9px;font:inherit}#ai-composer button{min-height:40px;min-width:40px;border:1px solid var(--app-border,#ded5b2);border-radius:8px;background:transparent;color:inherit;font:inherit;padding:7px 10px;cursor:pointer}#ai-composer button[type=submit],#ai-composer .ai-build{background:var(--app-accent,#b64932);color:var(--app-accent-ink,#fff)}#ai-composer button:disabled{opacity:.5}#ai-composer .ai-dialog,#ai-composer .ai-status{line-height:1.55}#ai-composer .ai-actions{display:flex;gap:8px;margin:12px 0}#ai-composer details{border-top:1px solid var(--app-border,#ded5b2);padding-top:12px;margin-top:14px}#ai-composer details p{font-size:12px;line-height:1.5}body:not([data-family=ranch]) #ai-composer-toggle{display:none}@media(max-width:600px){#ai-composer{top:auto;bottom:84px;right:8px;width:calc(100vw - 16px);height:44dvh;max-height:44dvh}}`;document.head.append(style);
